import networkx as nx
from itertools import product

def roman_dom(G):
    # compute roman domination number
    nodes = list(G.nodes())
    n = len(nodes)
    best = 2 * n
    for f in product([0, 1, 2], repeat=n):
        # check if roman dominating
        valid = True
        for i, u in enumerate(nodes):
            if f[i] == 0:
                # must have neighbor with 2
                has_two = any(f[nodes.index(v)] == 2 for v in G.neighbors(u))
                if not has_two:
                    valid = False
                    break
        if valid:
            cost = sum(f)
            if cost < best:
                best = cost
    return best

bad = []
for n in range(2, 7):
    for G in nx.graph_atlas_g():
        if len(G) == n and nx.is_connected(G):
            rad = nx.radius(G)
            rd = roman_dom(G)
            if rad + 1 > rd:
                bad.append((n, rad, rd, list(G.edges())))
                print(f"COUNTEREXAMPLE: n={n}, rad={rad}, rd={rd}, edges={list(G.edges())}")

print(f"Total counterexamples up to n=6: {len(bad)}")
'"

